                if 0 <= rr < h and 0 <= cc < w:
                    out.add((rr, cc))
    return out


def place_l(h, w, kind, corner):
    if corner == 'grid_tl':
        r0 = random.randint(0, 1)
        c0 = random.randint(0, 1)
    elif corner == 'grid_tr':
        r0 = random.randint(0, 1)
        c0 = w - 3 - random.randint(0, 1)
    elif corner == 'grid_bl':
        r0 = h - 3 - random.randint(0, 1)
        c0 = random.randint(0, 1)
    else:
        r0 = h - 3 - random.randint(0, 1)
        c0 = w - 3 - random.randint(0, 1)
    return {(r0 + dr, c0 + dc) for dr, dc in L_PATTERNS[kind]}


def sample_pivots(h, w, n, forbidden):
    rows = list(range(h))
    cols = list(range(w))
    for _ in range(200):
        rs = random.sample(rows, n)
        cs = random.sample(cols, n)
        random.shuffle(cs)
        pivots = list(zip(rs, cs))
        if any(p in forbidden for p in pivots):
            continue
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                if max(abs(pivots[i][0] - pivots[j][0]), abs(pivots[i][1] - pivots[j][1])) < 2:
                    ok = False
        if ok:
            return pivots
    return None


def moves_for_pivot(pivot, pivots, h, w, forbidden, clockwise):
    pivot_set = set(pivots)
    cands = []
    for d in DISTANCES:
        for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            sat = (pivot[0] + dr * d, pivot[1] + dc * d)
            if not in_bounds(sat, h, w):
                continue
            if sat in forbidden or sat in pivot_set:
                continue
            matches = sum(sat[0] == pr or sat[1] == pc for pr, pc in pivots)
            if matches "'!= 1:
                continue
            tdr, tdc = rotate_offset(dr * d, dc * d, clockwise)
            target = (pivot[0] + tdr, pivot[1] + tdc)
            oob = not in_bounds(target, h, w)
            if not oob:
                if target in forbidden or target in pivot_set:
                    continue
            cands.append((sat, None if oob else target, oob))
    random.shuffle(cands)
    return cands


def assign(cands, need_oob):
    n = len(cands)
    order = sorted(range(n), key=lambda i: len(cands[i]))
    sats = set()
    tgts = set()
    out = [None] * n

    def rec(k, used_oob):
        if k == n:
            return used_oob == need_oob
        rem = n - k
        if used_oob > need_oob or used_oob + rem < need_oob:
            return False
        idx = order[k]
        random.shuffle(cands[idx])
        for sat, tgt, oob in cands[idx]:
            if used_oob + int(oob) > need_oob:
                continue
            if sat in sats or sat in tgts:
                continue
            if tgt is not None and (tgt in sats or tgt in tgts):
                continue
            sats.add(sat)
            if tgt is not None:
                tgts.add(tgt)
            out[idx] = (sat, tgt, oob)
            if rec(k + 1, used_oob + int(oob)):
                return True
            sats.remove(sat)
            if tgt is not None:
                tgts.remove(tgt)
            out[idx] = None
        return False

    return out if rec(0, 0) else None

for trial in range(1000):
    h = random.randint(*GRID_H_RANGE)
    w = random.randint(*GRID_W_RANGE)
    n = random.randint(*PAIR_COUNT_RANGE)
    kind = random.choice(['"'top_left', 'top_right'])
    clockwise = kind == 'top_left'
    l_cells = place_l(h, w, kind, random.choice(['grid_tl', 'grid_tr', 'grid_bl', 'grid_br']))
    forbidden = expand(l_cells, h, w, 1)
    pivots = sample_pivots(h, w, n, forbidden)
    if not pivots:
        continue
    cands = [moves_for_pivot(p, pivots, h, w, forbidden, clockwise) for p in pivots]
    if not all(cands):
        continue
    can_oob = [any(o for _, _, o in x) for x in cands]
    if random.random() < 0.5:
        if not any(can_oob):
            continue
        max_oob = min(2, sum(can_oob), n - 1)
        if max_oob < 1:
            continue
        need_oob = random.randint(1, max_oob)
    else:
        need_oob = 0
    choice = assign(cands, need_oob)
    if choice is not None:
        print('ok', trial, h, w, n, kind, need_oob)
        break
else:
    print('failed')
